let all=[];const $=s=>document.querySelector(s);fetch('../data/components.json').catch(()=>fetch('components.json')).then(r=>r.json()).then(xs=>{all=xs;init()});
function init(){const cats=[...new Set(all.map(x=>x.category))].sort();$('#category').innerHTML+=[...cats].map(x=>`<option>${x}</option>`).join('');for(const el of ['q','assistant','category'])$('#'+el).addEventListener('input',render);$('#stats').className='stats';$('#stats').innerHTML=`<div><b>${all.length}</b><span>components</span></div><div><b>${all.filter(x=>x.assistant.includes('Coq')).length}</b><span>using Coq</span></div><div><b>${all.filter(x=>x.assistant.includes('Lean')).length}</b><span>using Lean</span></div>`;render()}
const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function render(){const q=$('#q').value.toLowerCase(),a=$('#assistant').value,c=$('#category').value;const xs=all.filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!a||x.assistant.includes(a))&&(!c||x.category===c));$('#empty').hidden=xs.length>0;$('#catalog').innerHTML=xs.map((x,i)=>`<article class="card"><div class="top"><span class="num">${String(i+1).padStart(2,'0')}</span><div><h3>${esc(x.name)}</h3><small>${esc(x.artifact)}</small></div><div class="tags"><span class="tag">${esc(x.assistant)}</span><span class="tag">${esc(x.category)}</span><br>${esc(x.maturity)}</div></div><details><summary>Inspect the verified claim</summary><div class="grid"><div class="spec"><h4>Exact specification</h4><p>${esc(x.spec)}</p></div><div><h4>Theorem / proof handle</h4><p>${esc(x.theorem)}</p></div><div><h4>Assumptions / trusted base</h4><p>${esc(x.assumptions)}</p></div><div><h4>Not proved</h4><p>${esc(x.excludes)}</p></div><div class="evidence"><h4>Evidence</h4><p>${x.evidence.map(e=>`<a href="${esc(e[1])}">${esc(e[0])}</a>`).join(' · ')}</p></div></div></details></article>`).join('')}
